function toHttp(error: unknown, log: NonNullable<AppOptions["log"]>) {
  if (error instanceof HttpError) return { status: error.status, code: error.code, message: error.message };
  if (error instanceof NotificationError) {
    const status = STATUS_BY_CODE[error.code] ?? 500;
    if (status >= 500) {
      log("notification API: server-side error", error);
      return { status, code: "INTERNAL", message: "internal error" };
    }
    return { status, code: error.code, message: error.message };
  }
  const type = (error as { type?: unknown } | null)?.type;
  if (type === "entity.parse.failed") return { status: 400, code: "INVALID_JSON", message: "body is not valid JSON" };
  if (type === "entity.too.large") return { status: 413, code: "BODY_TOO_LARGE", message: "body is over the size limit" };
  log("notification API: unexpected error", error);
  return { status: 500, code: "INTERNAL", message: "internal error" };
}

// real, src/queued-notifier.ts
applyReceipt(channel: Channel, providerId: string, receipt: Receipt): ReceiptOutcome {
  const key = `${channel}:${providerId}`;
  const recordId = this.sentBy.get(key);
  const delivery = recordId === undefined ? undefined : this.records.get(recordId)?.deliveries.find((d) => d.channel === channel);
  if (!delivery) {
    this.parked.set(key, mergeReceipt(this.parked.get(key), receipt));
    this.stats.receiptsParked++;
    return "parked";
  }
  const merged = mergeReceipt(delivery.receipt, receipt);
  if (merged === delivery.receipt) {
    this.stats.receiptsUnchanged++;
    return "unchanged";
  }
  delivery.receipt = merged;
  this.stats.receiptsApplied++;
  return "applied";
}

