const digest = (s: string) => createHash("sha256").update(s).digest();

// Constant time: comparing digests (always 32 bytes) means neither the content nor the LENGTH of the key leaks
// through how long a wrong guess takes to be refused.
function keyMatches(expected: Buffer, header: string | undefined): boolean {
  const match = /^Bearer (.+)$/.exec(header ?? "");
  return match !== null && timingSafeEqual(expected, digest(match[1]!));
}

// real, src/receipts.ts
export function verifyWebhook(secret: string, header: string | undefined, rawBody: Buffer, nowMs: number, toleranceMs = DEFAULT_TOLERANCE_MS): boolean {
  const match = /^t=(\d{1,12}),v1=([0-9a-f]{64})$/.exec(header ?? "");
  if (!match) return false;
  const t = Number(match[1]);
  if (Math.abs(nowMs - t * 1000) > toleranceMs) return false; // too old (a replay) or from the future
  return timingSafeEqual(hmac(secret, t, rawBody), Buffer.from(match[2]!, "hex"));
}

