close() {
  closing ??= (async () => {
    const closed = new Promise<void>((resolve, reject) => server.close((e) => (e ? reject(e) : resolve())));
    server.closeIdleConnections(); // keep-alive sockets with no request would otherwise hold close() open
    await closed;
    await worker.stop();
  })();
  return closing;
}

