// illustrative solution, not in the repo
export function verifyWebhookAny(
  secrets: string | readonly string[],
  header: string | undefined,
  rawBody: Buffer,
  nowMs: number,
  toleranceMs = DEFAULT_TOLERANCE_MS,
): boolean {
  const match = /^t=(\d{1,12})((?:,v1=[0-9a-f]{64}){1,4})$/.exec(header ?? "");
  if (!match) return false;
  const t = Number(match[1]);
  if (Math.abs(nowMs - t * 1000) > toleranceMs) return false;
  const sigs = match[2]!.split(",v1=").slice(1).map((h) => Buffer.from(h, "hex"));
  let ok = false;
  for (const secret of typeof secrets === "string" ? [secrets] : secrets) {
    const expected = hmac(secret, t, rawBody);
    for (const sig of sigs) ok = timingSafeEqual(expected, sig) || ok; // no early exit
  }
  return ok;
}

